      [L('Uzunlik', 'Длина', 'Length'), L('kesma', 'отрезок', 'segment'), '× 10', '1 dm = 10 cm'],
      [L('Yuz', 'Площадь', 'Area'), L('kvadrat', 'квадрат', 'square'), '× 100', '1 dm² = 100 cm²'],
      [L('Hajm', 'Объём', 'Volume'), L('kub', 'куб', 'cube'), '× 1 000', '1 dm³ = 1 000 cm³'],
      [L('Sig‘im', 'Вместимость', 'Capacity'), L('litr', 'литр', 'litre'), '× 1 000', '1 l = 1 000 ml']
